def red(s, a):
    if a['type'] == 'ADD_ITEM':
        p = a['payload']
        return {'items': s['items'] + [p], 'count': s['count'] + 1, 'total': s['total'] + p['price']}
    if a['type'] == 'REMOVE_ITEM':
        p = a['payload']
        return {'items': [i for i in s['items'] if i['id'] != p['id']],
                'count': s['count'] - 1, 'total': s['total'] - p['price']}
    return s

